const circles = {user:'<circle cx="12" cy="6" r="4"/>',users:'<circle cx="9" cy="6" r="4"/>',clock:'<circle cx="12" cy="12" r="9"/>',timer:'<circle cx="12" cy="14" r="8"/>',sun:'<circle cx="12" cy="12" r="4"/>',target:'<circle cx="12" cy="12" r="7"/><circle cx="12" cy="12" r="3"/>',info:'<circle cx="12" cy="12" r="9"/>',walk:'<circle cx="14" cy="3" r="2"/>'};
const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true">${circles[name] || ''}<path d="${paths[name] || paths.leaf}"/></svg>`;
const tree = (stage=3) => `<img src="/trees/stage-${stage}-healthy.webp" alt="온주의 나무" draggable="false">`;
const button = (text, action, cls='primary') => `<button class="${cls}" data-action="${action}">${text}</button>`;
const ib = (name,label,action) => `<button class="icon-button" aria-label="${label}" data-action="${action}">${icon(name)}</button>`;
const tag = (text,kind='') => `<span class="tag ${kind}">${text}</span>`;
const section = (title,other='') => `<div class="section-head"><h2>${title}</h2>${other}</div>`;
const progress = n => `<div class="progress" style="--progress:${n}%" role="img" aria-label="진행률 ${n}%"><i></i></div>`;
const option = (name,title,value,action='option') => `<button class="option-row" data-action="${action}">${icon(name)}<span>${title}</span><strong>${value}</strong>${icon('chevron').replace('<svg','<svg class="chev"')}</button>`;
const row = (name,title,sub,action,tone='') => `<button class="list-row" data-action="${action}"><span class="tile ${tone}">${icon(name)}</span><span class="flex-one"><strong>${title}</strong>${sub?`<span class="sub">${sub}</span>`:''}</span>${icon('chevron')}</button>`;
const disclosure = (label,content) => `<details class="disclosure"><summary>${label}</summary>${content}</details>`;
const field = (label,placeholder,type='text') => `<label class="input-label">${label}<input class="field" style="margin-top:9px" type="${type}" placeholder="${placeholder}" autocomplete="off"></label>`;
const state = {screen:'home',mode:'gallery',status:'normal',step:1,stats:'주간',count:4,gallery:'daily'};

