function syncChip(){return state.status==='normal'?`<button class="sync-chip" data-action="status" aria-label="저장 상태: 모두 저장됨">${icon('cloud')}</button>`:'';}
const top = (title,back='home',extra='') => `<header class="screen-header">${back?ib('back','뒤로 가기',`go:${back}`):''}<h1>${title}</h1>${extra||syncChip()}</header>`;
const tabs = id => `<div class="tabs" aria-label="홈 기록 종류">${[['home','개인'],['faith','신앙'],['todos','할 일']].map(([s,t])=>`<button data-action="go:${s}" class="${s===id?'active':''}" aria-pressed="${s===id}">${t}</button>`).join('')}</div>`;
const days = () => `<div class="days" aria-label="날짜 선택">${['월','화','수','목','금','토','일'].map((d,i)=>`<button class="${i===2?'active':''}" data-action="day" aria-label="${i===6?'11월 1일':`10월 ${26+i}일`}${i===2?' 오늘':''}" ${i>2?'disabled':''}><small>${d}</small><span>${26+i>31?1:26+i}</span><i></i></button>`).join('')}</div>`;
