const groupCard = (title,sub,privateGroup=false) => `<button class="group-card" data-action="go:groupdetail"><div class="spread"><span class="tile ${privateGroup?'gold':''}">${icon(privateGroup?'lock':'walk')}</span>${tag('모집 중')}</div><h2>${title}</h2><p class="caption muted">${sub}</p><div class="group-meta">${avatars()}<span>${privateGroup?'비공개 · ':''}4/6명 · 11.24까지</span></div></button>`;
const notes = () => `<div class="pill-tabs" aria-label="기록 종류">${['전체','말씀','기도'].map((t,i)=>`<button data-action="filter:${t}" class="${i===0?'active':''}" aria-pressed="${i===0}">${t}</button>`).join('')}</div>${draft()}<article class="note-card" data-category="기도"><div class="meta"><span>10.28 수요일</span>${tag('기도','gold')}</div><button class="note" data-action="go:noteedit">조급함을 내려놓고<br>동료의 말을 끝까지 듣게 해주세요.<br>작은 배려를 실천하겠습니다.</button><div class="spread" style="margin-top:14px"><span class="tiny muted">마음을 정리하는 기도</span>${ib('more','10월 28일 기도 더보기','note-menu')}</div></article><article class="note-card" data-category="말씀"><div class="meta"><span>10.27 화요일</span>${tag('말씀')}</div><button class="note" data-action="go:noteedit">내일 일을 위하여 염려하지 말라.<br>오늘 할 수 있는 일에 마음을 두기.</button><div class="tiny muted" style="margin-top:14px">마태복음 6:34</div></article><article class="note-card" data-category="기도"><div class="meta"><span>10.26 월요일</span>${tag('응답받음','gold')}</div><button class="note" data-action="go:noteedit">작은 대화로 서로를 이해한 하루.<br>먼저 다가갈 용기를 주셔서 감사합니다.</button></article>`;
function home(id){const faith=id==='faith',todo=id==='todos';return {header:`<header class="screen-header home-header"><div class="flex-one"><p class="subdate">10월 28일 수요일</p><h1>오늘, 가볍게<span class="brand-period" aria-hidden="true">.</span></h1></div>${ib('book','하루 일기','go:diary')}${syncChip()}</header>`,body:`${days()}${tabs(id)}${section(todo?'오늘 할 일':faith?'오늘의 신앙':'오늘의 실천',`<button class="text-button" data-action="remaining">남은 것만 ${icon('down')}</button>`)}${todo?`${habit('list','회의 자료 마무리','오늘')}${habit('list','치과 예약하기','',true)}${draft()}`:faith?`${habit('book','말씀 한 구절','아침 · 5분',false,'gold')}${habit('heart','감사 기도','저녁 · 2분',false,'gold')}${row('book','은혜 기록','', 'go:notes','gold')}`:`<div class="spread" style="margin:15px 0 2px"><span class="kicker">아침 루틴</span><small>1/3</small></div>${habit('drop','물 한 잔','',true)}${habit('walk','가볍게 몸 풀기','5분')}${habit('book','책 두 쪽 읽기','10분')}`}${button(`${icon('plus')} ${todo?'할 일':faith?'신앙 루틴':'실천'} 추가`,`go:${todo?'todoform':faith?'faithform':'habitform'}`,'text-button')}${!todo?`<button class="growth-strip" data-action="go:goals">${tree(1)}<span><strong>조금씩 자라는 나</strong><small>목표 2개 · 연속 4일</small></span>${icon('chevron')}</button>`:''}`,nav:'home'};}
function form(id){const config={habitform:['새 습관','습관 이름','가볍게 몸 풀기','leaf'],routineform:['새 루틴','루틴 이름','나를 깨우는 아침','list'],faithform:['새 신앙 루틴','루틴 이름','감사 기도','book'],todoform:['새 할 일','할 일','회의 자료 마무리','edit'],goalform:['새 목표','어떤 사람이 되고 싶나요?','꾸준히 몸을 돌보는 사람','target'],weeklyform:['주간 목표','연결할 습관','퇴근 후 산책','calendar']}[id];const [title,label,value,i]=config;
 let body=`<div class="spread"><div class="form-icon">${icon(i)}</div><button class="text-button" data-action="draft-info">${icon('folder')} 기기에 보관</button></div>`;
 if(id==='weeklyform')body+=row('walk','퇴근 후 산책','연결된 습관','option')+`<div class="card soft" style="text-align:center;padding:27px"><p class="caption">일주일에</p><div class="spread" style="margin:18px 30px">${ib('back','횟수 줄이기','minus')}<strong class="big" id="target-count">${state.count}<small> 회</small></strong>${ib('plus','횟수 늘리기','plus')}</div><small>10.26 – 11.01</small></div><p class="caption muted">습관을 체크하면 함께 채워져요.</p>`;
 else {body+=`<label class="input-label">${label}<input class="field title-field" aria-label="${label}" value="${value}"></label>`;
 if(id==='todoform')body+=option('calendar','날짜','10.28 오늘','date')+draft();
 else if(id==='goalform')body+=option('leaf','분류','개인','category')+option('calendar','기간','10.28 – 11.27','period')+`<p class="caption muted" style="margin-top:20px">저장 후 함께 실천할 습관을 연결해요.</p>`+disclosure('실천 계획 · 선택',field('어떻게 실천할까요?','예: 퇴근 후 10분 걷기')+field('어려운 날에는','예: 2분 몸 풀기'));
 else if(id==='routineform')body+=section('함께할 습관',button('추가','option','text-button'))+row('drop','물 한 잔','1번째','order')+row('walk','가볍게 몸 풀기','2번째','order')+option('clock','실행 시점','기상 후','time')+disclosure('타이머 · 5분',field('총 시간','5','number'));
 else body+=(id==='faithform'?`<div class="pill-tabs">${button('말씀','choice','')}${button('기도','choice','active')}</div>`:'')+option('calendar','반복','매일','repeat')+option('bell','알림','사용 안 함','alarm')+option('link','목표 연결','선택 안 함','goal-select')+disclosure('실천을 돕는 설정',option('clock','실행 시점','기상 후','time')+option('timer','타이머','5분','duration')+field('2분 시작 행동','예: 운동복 입기')+field('어려운 날의 대체 행동','예: 가볍게 기지개'));
 }
 return {header:top(title,id==='goalform'||id==='weeklyform'?'goals':'home'),body,action:button(id==='goalform'?'저장하고 실천 연결':'저장',id==='goalform'?'go:connect':'save')};}
function review(){const step=state.step;let body=`<div class="review-count">10.26 – 11.01 · ${step}/4</div><div class="review-steps">${[1,2,3,4].map(n=>`<span class="${n<=step?'active':''}"></span>`).join('')}</div>`;
 if(step===1)body+=`<h2 class="review-step-title">이번 주의 작은 걸음</h2>${metric()}<div class="bar-chart" aria-label="월요일 75%, 화요일 100%, 수요일 60%">${[75,100,60,0,0,0,0].map((n,i)=>`<div class="${i===2?'today':''}" aria-label="${i===2?'오늘':''}"><i style="height:${Math.max(4,n)}%"></i><small>${'월화수목금토일'[i]}</small></div>`).join('')}</div>${section('주간 목표')}<div class="week-goal"><span class="tile">${icon('walk')}</span><span><strong>퇴근 후 산책</strong><small>주 4회</small></span><b>3<small>/4</small></b></div>${disclosure('개인·신앙과 목표별 기록',`<p class="caption">개인 80% · 신앙 75%<br>이달의 목표 2개 · 연결 습관 3개</p>`)}`;
 if(step===2)body+=`<h2 class="review-step-title">이번 주, 어땠나요?</h2>${moods()}<label class="input-label">남기고 싶은 한마디<textarea class="editor" placeholder="기억하고 싶은 순간을 적어보세요.">조금 늦어도 멈추지 않은 나에게 고마워요.</textarea></label>`;
 if(step===3)body+=`<h2 class="review-step-title">다음 걸음을 정해요</h2><div class="pill-tabs">${button('개인','choice','active')}${button('신앙','choice','')}</div>${section('아침 루틴',tag('1/2 조정'))}${row('walk','가볍게 몸 풀기','매일 → 월·수·금','adjust')}${row('drop','물 한 잔','매일 · 유지','adjust')}${button(`${icon('plus')} 실천 추가`,'go:habitform','text-button')}`;
 if(step===4)body+=`<h2 class="review-step-title">이대로 이어갈까요?</h2><div class="card soft"><div class="spread"><strong style="font-size:14px">실천 조정 1개</strong>${tag('오늘부터')}</div><p class="caption" style="margin-top:12px">가볍게 몸 풀기<br><b>매일 → 월·수·금</b></p></div><p class="caption muted">완료하면 10월 28일부터 적용돼요.</p>${field('다음 주 한마디','꾸준히, 조금씩')}${option('users','모임에 공유','공유 안 함','share-select')}${disclosure('저장할 항목 확인',`<p class="caption">주간 결산, 실천 조정, 리뷰를 저장합니다. 이미 저장된 항목은 유지하고, 실패한 항목만 이어서 저장할 수 있어요.</p>`)}`;
 return {header:top('주간 리뷰','stats',button('초안','draft','text-button')),body,action:button(step===4?'리뷰 완료':'다음',step===4?'review-complete':'review-next')};}
function view(id){if(['home','faith','todos'].includes(id))return home(id);if(id.endsWith('form'))return form(id);if(id==='review')return review();
 switch(id){
 case 'notes':return {header:top('은혜 기록','faith',ib('stats','기록 통계','go:stats')),body:notes(),nav:'home'};
 case 'noteedit':return {header:top('기도 기록','notes',ib('more','기록 더보기','note-menu')),body:`<div class="spread" style="margin:8px 0 20px"><span class="caption muted">10월 28일 수요일</span><button class="text-button" data-action="draft-info">${icon('folder')} 기기에 보관</button></div>${tag('마음을 정리하는 기도','gold')}<label class="input-label">기도 내용<textarea class="editor" aria-label="기도 내용" style="margin-top:14px">조급함을 내려놓고
동료의 말을 끝까지 듣게 해주세요.
작은 배려를 실천하겠습니다.</textarea></label><div class="setting-row"><span class="tile gold">${icon('heart')}</span><strong>응답받은 기도</strong><button class="toggle" role="switch" aria-label="응답받은 기도" aria-checked="false" data-action="toggle"><i></i></button></div>`,action:button('저장','save')};
 case 'diary':return {header:top('하루 일기'),body:`<div class="date-row">${ib('back','전날 일기','previous-day')}<span>10월 28일 수요일</span>${ib('chevron','다음 날 일기','next-day')}</div>${draft('어제의 초안 1개')}${moods()}<label class="input-label">오늘의 마음<textarea class="editor" aria-label="오늘의 마음">서두르지 않고 내 속도로 마무리했다.
오늘의 작은 성취를 기억하고 싶다.</textarea></label><div class="spread"><button class="text-button" data-action="draft-info">${icon('folder')} 기기에 보관</button>${ib('more','일기 더보기','note-menu')}</div>`,action:button('저장','save')};
 case 'goals':return {header:top('나의 목표','home',ib('plus','목표 추가','goal-add')),body:`${section('이번 주',button(`${icon('plus')} 추가`,'go:weeklyform','text-button'))}<div class="week-goal"><span class="tile">${icon('walk')}</span><span class="flex-one"><strong>퇴근 후 산책</strong><small>주 4회 · 11.01까지</small></span><button data-action="go:weeklyform" aria-label="주간 목표 3회 완료, 4회 목표 수정"><b>3<small>/4</small></b></button></div>${progress(75)}${section('이달의 목표',`<small>2개</small>`)}${goal('활기찬 아침 만들기',64)}${goal('꾸준히 몸을 돌보는 사람',32,'11.27까지')}${button('지난 목표 보기','history','text-button')}`,nav:'home'};
 case 'goaldetail':return {header:top('목표 상세','goals',ib('more','목표 더보기','goal-menu')),body:`${tag('개인')}<h2 class="large-copy" style="margin:18px 0">활기찬 아침 만들기</h2><p class="caption muted">10.01 – 10.31</p><div class="card soft"><div class="spread"><span class="caption">전체 진척</span>${ib('info','진척 계산 기준','metric-info')}</div><div class="big">64<small>%</small></div>${progress(64)}<p class="tiny muted">목표 기간 전체의 예정일 기준</p></div>${option('calendar','지금까지 기록률','78%','metric-info')}${section('연결된 실천',button('관리','go:connect','text-button'))}${row('walk','가볍게 몸 풀기','월·수·금 · 5분','go:habitform')}${row('drop','물 한 잔','매일','go:habitform')}`,action:button('오늘 실천하기','go:home')};
 case 'connect':return {header:top('실천 연결','goals'),body:`<div class="card soft"><span class="kicker">나의 목표</span><p style="font-size:16px;font-weight:700;margin-top:8px">활기찬 아침 만들기</p></div>${section('연결된 실천',`<small>2개</small>`)}${row('walk','가볍게 몸 풀기','개인 습관','connection-menu')}${row('drop','물 한 잔','개인 습관','connection-menu')}${button(`${icon('plus')} 기존 습관 연결`,'link-picker','secondary')}${button('새 습관 만들기','go:habitform','text-button')}${disclosure('연결을 바꾸면?',`<p class="caption">연결은 오늘부터 바뀌어요. 습관과 과거 수행 기록은 그대로 남습니다.</p>`)}`,action:button('홈에서 실천','go:home')};
 case 'stats':return {header:top('성장 기록','',ib('info','통계 기준','metric-info')),body:`<div class="tabs" style="gap:24px">${['주간','목표','습관','기록'].map(t=>`<button class="${state.stats===t?'active':''}" data-action="stats:${t}" aria-pressed="${state.stats===t}">${t}</button>`).join('')}</div>${state.stats==='주간'?`<div class="date-row" style="margin-top:18px">${ib('back','이전 주','history')}<span>10.26 – 11.01</span>${ib('chevron','다음 주','next-week')}</div><div class="metric-grid"><div><small>이번 주 기록률</small><strong>78<small>%</small></strong></div><div><small>지난주보다</small><strong>+12<small>%p</small></strong></div></div><div class="bar-chart">${[80,100,55,0,0,0,0].map((n,i)=>`<div class="${i===2?'today':''}"><i style="height:${Math.max(n,4)}%"></i><small>${'월화수목금토일'[i]}</small></div>`).join('')}</div>${section('나의 실천')}${row('leaf','개인','기록률 80%','metric-info')}${row('book','신앙','기록률 75%','metric-info','gold')}${row('edit','한 주 돌아보기','주간 리뷰','go:review')}`:state.stats==='목표'?goal('활기찬 아침 만들기',64)+goal('꾸준히 몸을 돌보는 사람',32):state.stats==='습관'?`${section('꾸준히 이어가는 실천')}${row('drop','물 한 잔','이번 주 3/3일','metric-info')}${row('walk','가볍게 몸 풀기','이번 주 2/3일','metric-info')}`:`${section('기록한 마음')}${row('edit','하루 일기','이번 주 3일','go:diary')}${row('book','은혜 기록','기도 2 · 말씀 1','go:notes')}${row('edit','주간 리뷰','지난 리뷰 보기','go:reviewresult')}`}`,nav:'stats'};
 case 'tree':return {header:top('나의 나무'),body:`<div class="tree-center">${tree(3)}<h2>차곡차곡, 자라는 중</h2><p class="caption muted" style="margin-top:10px">어린 나무 · 3단계</p></div>${metric()}${progress(64)}<div class="spread"><small>다음 성장까지</small><small>36점</small></div>${disclosure('나무는 어떻게 자라나요?',`<p class="caption">실천을 기록하며 성장해요. 쉬는 날도 돌아올 수 있는 나무입니다.</p>`)}${row('sun','숲 테마','나의 풍경 바꾸기','go:themes')}`,nav:'home'};
 case 'themes':return {header:top('숲 테마','profile'),body:`<div class="theme-grid">${['기본 숲','봄빛','여름 숲','가을 숲'].map((t,i)=>`<button class="theme-card ${i===0?'active':''}" data-action="${i<2?'theme':'theme-locked'}" style="background:${['var(--soft)','var(--linen)','var(--soft)','var(--red-soft)'][i]}">${tree(i+1)}${t}<br><small>${i===0?'사용 중':i===1?'선택하기':'잠김'}</small></button>`).join('')}</div>`,nav:'profile'};
 case 'reviewresult':return {header:top('한 주의 기록','stats'),body:`<p class="caption muted">10.26 – 11.01</p><div class="tree-center" style="margin:0">${tree(1)}</div><p class="quote">조금 늦어도 멈추지 않은<br>나에게 고마워요.</p>${metric()}${section('새롭게 이어갈 실천')}<div class="card soft"><strong style="font-size:14px">가볍게 몸 풀기</strong><p class="caption" style="margin-top:7px">월·수·금 · 10.28부터 적용</p></div><p class="caption muted">${icon('check')} 리뷰 저장 완료</p>`,action:button('오늘로 돌아가기','go:home')};
 case 'groups':return {header:top('소모임','',`${ib('lock','초대 코드로 참여','go:invite')}${ib('plus','소모임 만들기','go:groupnew')}`),body:`<div class="tabs"><button class="active" data-action="group-filter:mine">내 모임 <sup>2</sup></button><button data-action="group-filter:explore">둘러보기</button></div>${groupCard('함께 걷는 점심시간','점심 뒤, 가볍게 10분')}${groupCard('하루 한 줄 말씀','말씀으로 하루를 시작해요',true)}${row('share','오늘의 인증','', 'go:share')}`,nav:'groups'};
 case 'groupdetail':return {header:top('우리 소모임','groups',ib('more','소모임 관리','group-menu')),body:`<div class="cover">${tag('모집 중')}<h2>함께 걷는<br>점심시간</h2><span class="cover-botanical" aria-hidden="true">${icon('leaf')}${icon('leaf')}</span></div><div class="spread"><span class="caption muted">4/6명 · 11.24까지</span>${tag('공개')}</div><div class="tabs"><button class="active" data-action="group-tab:activity">활동</button><button data-action="group-tab:about">소개·약속</button></div><div id="group-content">${section('이번 주 함께한 걸음')}${['서연','민준','하은'].map((n,i)=>`<div class="member-line"><span class="avatar">${n[0]}</span><span>${n}</span>${progress([75,50,100][i])}<b>${[75,50,100][i]}%</b></div>`).join('')}${section('나눔')}<p class="note">오늘은 바람이 좋아서<br>조금 더 걸었어요.</p><button class="text-button" data-action="cheer">${icon('heart')} 응원 3</button></div>`,action:button(`${icon('share')} 오늘 인증`,'go:share')};
 case 'groupnew':return {header:top('소모임 만들기','groups'),body:`<div class="form-icon">${icon('users')}</div>${field('모임 이름','함께 걷는 점심시간')}${field('함께할 일','점심 뒤 10분 걷기')}${option('calendar','기간','10.28 – 11.24','period')}${option('users','정원','6명','capacity')}${option('lock','공개 범위','비공개','privacy')}${disclosure('우리의 약속',`<label class="caption"><input type="checkbox" checked> 서로의 속도를 존중해요</label><br><label class="caption"><input type="checkbox" checked> 주 3회 이상 함께해요</label>`)}<p class="caption muted" style="margin-top:18px">비공개 모임은 초대 코드로만 참여해요.</p>`,action:button('모임 만들기','create-group')};
 case 'invite':return {header:top('초대로 참여','groups'),body:`<div class="form-icon">${icon('lock')}</div><h2 class="large-copy">함께할 초대가 왔나요?</h2>${field('초대 코드','받은 코드를 붙여넣으세요')}<p class="caption muted" style="margin-top:16px">초대는 한 명만 사용할 수 있어요.</p>${disclosure('코드를 확인할 수 없나요?',`<p class="caption">만료되었거나 사용된 코드는 새로 받아야 해요. 이미 요청했다면 현재 참여 상태를 먼저 확인합니다.</p>`)}`,action:button('초대 확인','invite-preview')};
 case 'share':return {header:top('오늘 인증','groups'),body:`${option('users','공유할 모임','함께 걷는 점심시간','share-select')}${section('오늘의 실천')}<label class="list-row"><input type="checkbox" checked><span class="tile">${icon('walk')}</span><strong>점심 후 10분 걷기</strong></label><label class="input-label">한마디 · 선택<textarea class="editor" placeholder="오늘 함께 나누고 싶은 이야기">걷고 나니 오후가 한결 가벼워요.</textarea></label><p class="caption muted">선택한 모임의 멤버에게 공개돼요.</p>`,action:button('모임에 공유','share-confirm')};
 case 'timer':return {header:top('가볍게 몸 풀기','home',ib('more','타이머 설정','option')),body:`<p class="caption muted" style="text-align:center;margin-top:16px">아침 루틴 · 2/3</p><div class="timer-ring"><strong>05:00</strong><small>내 속도로, 천천히</small></div><div class="spread" style="justify-content:center;gap:25px">${ib('refresh','타이머 다시 시작','timer-reset')}${button(icon('play')+' 시작','timer-play','primary')}${ib('check','실천 완료','timer-done')}</div>${button('다음: 물 한 잔','go:home','text-button')}`};
 case 'profile':return {header:top('나의 온주',''),body:`<div class="row" style="margin:18px 0 30px"><span class="tile" style="width:58px;height:58px;border-radius:20px">${icon('user')}</span><div><strong style="font-size:19px">서연</strong><p class="tiny muted" style="margin-top:5px">나만의 속도로, 온전히</p></div></div>${row('calendar','생활 설정','주 시작 월요일 · 체크 마감 오전 6시','life-settings')}${row('bell','알림','아침 07:00 · 저녁 21:00','go:notifications')}${row('folder','보관함','','go:archive')}${row('sun','숲 테마','기본 숲','go:themes')}${row('cloud','저장 상태','모두 저장됨','status')}${section('계정')}${row('user','계정 관리','','account')}<p class="tiny muted" style="margin-top:26px">온주 · 1.0</p>`,nav:'profile'};
 case 'notifications':return {header:top('알림','profile'),body:`<button class="draft-row" data-action="permission">${icon('bell')} 알림 권한 필요 <span class="flex-one"></span>설정 ${icon('chevron')}</button>${section('하루 알림')}${[['sun','아침','07:00'],['moon','저녁','21:00'],['edit','주간 리뷰','일요일 20:00']].map(([i,t,time])=>`<div class="setting-row">${icon(i)}<div class="flex-one"><strong>${t}</strong><small>${time}</small></div><button class="toggle" role="switch" aria-checked="false" aria-label="${t} 알림" data-action="permission"><i></i></button></div>`).join('')}${disclosure('알림이 오지 않나요?',`<p class="caption">기기 알림 권한과 앱의 시간을 확인해요. 권한을 허용한 뒤 원하는 알림을 켤 수 있어요.</p>`)}`};
 case 'archive':return {header:top('보관함','profile'),body:`${row('walk','점심 후 산책','10.20 보관','restore')}${row('book','자기 전 독서','10.15 보관','restore')}${disclosure('보관한 기록은?',`<p class="caption">과거 수행 기록은 통계에 남아 있어요. 복원하면 오늘부터 다시 시작합니다.</p>`)}`};
 case 'login':return {header:'',body:`<div class="auth-hero">${tree(1)}<h2>온주</h2><p>나만의 속도로, 온전히.</p></div>${button('Google로 계속하기','auth-demo','social')}${button('카카오로 계속하기','auth-demo','social kakao')}<details class="disclosure"><summary>이메일로 로그인</summary>${field('이메일','you@example.com','email')}${field('비밀번호','비밀번호','password')}${button('로그인','auth-demo')}${button('비밀번호 찾기','go:password','text-button')}</details><div style="text-align:center">${button('처음이라면 회원가입','go:signup','text-button')}</div>`};
 case 'signup':return {header:top('회원가입','login'),body:`${field('이름','어떻게 불러드릴까요?')}${field('이메일','you@example.com','email')}${field('비밀번호','6자 이상','password')}${field('비밀번호 확인','한 번 더 입력','password')}<p class="tiny muted" style="margin-top:20px">가입 후 이메일 인증을 진행해요.</p>`,action:button('가입하기','auth-demo')};
 case 'password':return {header:top('비밀번호 재설정','login'),body:`<div class="form-icon">${icon('lock')}</div><h2 class="large-copy">새 비밀번호를 정해요</h2>${field('새 비밀번호','6자 이상','password')}${field('새 비밀번호 확인','한 번 더 입력','password')}${disclosure('재설정 링크가 만료됐나요?',`<p class="caption">로그인 화면에서 재설정 메일을 다시 요청해 주세요.</p>${button('로그인으로','go:login','text-button')}`)}`,action:button('변경하기','auth-demo')};
 case 'onboarding':return {header:top('처음 시작해요','login',button('건너뛰기','go:home','text-button')),body:`<div class="auth-hero">${tree(0)}<h2 style="font-size:25px">작은 실천 하나면<br>충분해요.</h2></div>${field('이름','서연')}${section('오늘 시작할 작은 실천')}${row('drop','물 한 잔 마시기','','go:habitform')}${row('book','말씀 한 구절 읽기','','go:faithform','gold')}${row('plus','직접 정하기','','go:habitform')}`};
 case 'conflicts':return {header:top('변경 내용 비교','home',ib('refresh','최신 내용 다시 확인','conflict-refresh')),body:`<p class="caption muted">10.28 기도 · 다른 기기에서 수정됐어요.</p><p class="caption" style="margin-top:8px">내 입력은 이 기기에 남아 있어요.</p><label class="compare-card"><header><input type="radio" name="conflict-choice" value="server">저장된 내용</header><p>오늘은 <mark>가족에게 먼저</mark><br>다가갈 용기를 주세요.</p></label><label class="compare-card"><header><input type="radio" name="conflict-choice" value="mine" checked>내 입력</header><p>조급함을 내려놓고<br><mark>동료의 말을 끝까지</mark> 듣게 해주세요.</p></label>${disclosure('전체 내용과 상태',`<p class="caption">저장된 내용: 오늘은 가족에게 먼저 다가갈 용기를 주세요.<br>내 입력: 조급함을 내려놓고 동료의 말을 끝까지 듣게 해주세요.<br>수행 상태: 쉬어감 · 변경하지 않음<br>다른 날짜의 기록은 유지됩니다.</p>`)}<p class="caption muted" style="margin-top:14px">선택한 기록의 메모만 바꿔요.</p>`,action:button('선택한 내용 사용','conflict-confirm')};
 case 'empty':return {header:top('나의 실천'),body:`<div class="empty-state">${icon('leaf')}<h2>작게 하나 시작해볼까요?</h2><p>오늘 해보고 싶은 일을 더해요.</p></div>${button(`${icon('plus')} 실천 추가`,'go:habitform')}`};
 default:return home('home');
 }}

function phone(id){
 const v=view(id);
 if(state.status==='failed')v.body=v.body.replaceAll('기기에 보관</button>','보관 실패</button>');
 if(state.status!=='normal')v.body=v.body.replaceAll('모두 저장됨',state.status==='failed'?'기기 보관 실패':state.status==='offline'?'전송 대기 2개':'비교할 변경 1개');
 return `<div class="phone" data-screen="${id}" data-status="${state.status}" data-palette="${colorStory(id).family}"><div class="device-bar"><span>9:41</span><span>${icon('signal')}${icon('battery')}</span></div>${v.header}${state.status==='failed'?`<button class="error-strip" data-action="status">${icon('alert')} 기기에 저장 안 됨 · 닫기 전 확인</button>`:state.status!=='normal'?`<button class="state-strip" data-action="status">${icon(state.status==='offline'?'offline':'alert')}<span>${state.status==='offline'?'저장 대기 2 · 기기에 보관':'다른 기기 변경 1개'}</span><b>확인</b>${icon('chevron')}</button>`:''}<main class="screen-scroll">${v.body}</main>${v.action?`<div class="bottom-action">${v.action}</div>`:''}${v.nav?nav(v.nav):''}</div>`;
}
const groups=[...new Set(screens.map(s=>s[1]))];
function picker(){return `<select class="screen-picker" aria-label="시안 화면 선택">${groups.map(g=>`<optgroup label="${g}">${screens.filter(s=>s[1]===g).map(s=>`<option value="${s[0]}" ${s[0]===state.screen?'selected':''}>${s[2]}</option>`).join('')}</optgroup>`).join('')}</select>`;}
function rationale(id){const s=meta(id),c=colorStory(id);return `<aside class="notes-panel"><span class="eyebrow">COLOR STORY ${String(screens.findIndex(s=>s[0]===id)+1).padStart(2,'0')} / ${screens.length}</span><h2>${s.title}</h2><p class="color-ratio">${c.ratio}</p><div class="color-role"><i class="dot linen"></i><div><h3>리넨</h3><p>${c.linen}</p></div></div><div class="color-role"><i class="dot parsley"></i><div><h3>파슬리 그린</h3><p>${c.green}</p></div></div><div class="color-role"><i class="dot tomato"></i><div><h3>토마토 레드</h3><p>${c.tomato}</p></div></div><details class="disclosure"><summary>정보 구조와 유지할 기능</summary><p class="caption">${s.change}</p><p class="caption">유지: ${s.keep}</p></details><div class="meta-note">${s.route}<br>기존 UI 간결화 방향을 유지한 색상 시안입니다.</div></aside>`;}
function renderGallery(){const g=gallerySets[state.gallery];return `<div class="gallery"><div class="gallery-heading"><div><span class="eyebrow">ONJU · COLOR CONCEPT 02</span><h1>${g.title}</h1><p>${g.description}</p></div><button class="text-button" data-action="mode:detail">${screens.length}개 화면 보기 ${icon('chevron')}</button></div>${swatches()}<nav class="gallery-tabs" aria-label="시안 화면 묶음">${[['daily','매일의 온주'],['together','성장과 함께'],['writing','작성과 리뷰'],['brand','브랜드와 상태']].map(([k,t])=>`<button class="${state.gallery===k?'active':''}" aria-pressed="${state.gallery===k}" data-action="gallery:${k}">${t}</button>`).join('')}</nav><div class="gallery-phones">${g.screens.map(([id,title,cap])=>`<div><div class="phone-label"><strong>${title}</strong><button data-action="go:${id}" class="text-button">자세히 ${icon('chevron')}</button></div>${phone(id)}<p class="gallery-caption">${cap}</p></div>`).join('')}</div><div class="design-rules"><div><strong><i class="dot linen"></i> 리넨으로 여백을</strong><p>화면의 바탕과 읽기·입력 영역.</p></div><div><strong><i class="dot parsley"></i> 그린으로 중심을</strong><p>제목, 주요 행동, 선택과 완료.</p></div><div><strong><i class="dot tomato"></i> 레드로 생기를</strong><p>오늘, 응원, 작은 강조와 명확한 주의.</p></div></div></div>`;}
function render(){document.title='온주 · 리넨 · 파슬리 그린 · 토마토 레드';document.querySelector('#design-root').innerHTML=`<header class="board-top"><div><div class="brand">${icon('leaf')}온주<span class="brand-period" aria-hidden="true">.</span><span class="version">COLOR CONCEPT 02</span></div><p class="board-title">리넨 · 파슬리 그린 · 토마토 레드</p></div><div class="board-actions">${[['gallery','한눈에'],['detail','화면별 시안'],['map','색상 가이드']].map(([m,t])=>`<button data-action="mode:${m}" class="${state.mode===m?'active':''}" aria-pressed="${state.mode===m}">${t}</button>`).join('')}<select aria-label="저장 상태 시나리오" id="status-select">${[['normal','저장 정상'],['offline','오프라인'],['conflict','충돌 발생'],['failed','기기 저장 실패']].map(([v,t])=>`<option value="${v}" ${v===state.status?'selected':''}>${t}</option>`).join('')}</select></div></header>${state.mode==='gallery'?renderGallery():state.mode==='detail'?`<div class="workspace"><nav class="screen-index" aria-label="시안 화면 목록">${groups.map(g=>`<div class="index-group"><h2>${g}</h2>${screens.filter(s=>s[1]===g).map(s=>`<button class="${s[0]===state.screen?'active':''}" data-action="go:${s[0]}" ${s[0]===state.screen?'aria-current="page"':''}>${icon(s[4])}${s[2]}</button>`).join('')}</div>`).join('')}</nav><div class="mobile-picker">${picker()}</div><div class="preview-stage"><div class="phone-label"><strong>${meta(state.screen).title}</strong><span>3 COLOR · 390px</span></div>${phone(state.screen)}</div>${rationale(state.screen)}</div>`:renderMap()}<footer class="footnote">색상 시안 · 예시 데이터 · 실제 저장·공유 없음 · <a href="./quiet-ui-2026-10-28.html">이전 시안</a></footer>`;}
function renderMap(){return `<div class="route-map"><h1>온주의 세 가지 색</h1><p>지정해주신 세 가지 색상 코드입니다. 밝은 토마토 레드는 포인트와 면에, 작은 글자는 파슬리 그린으로 구성했습니다.</p>${swatches()}<div class="palette-principles"><div><strong>넓은 리넨</strong><p>읽고 쓰는 화면은 리넨이 중심입니다.</p></div><div><strong>또렷한 파슬리</strong><p>완료·선택·저장에는 그린을 일관되게 씁니다.</p></div><div><strong>작게, 토마토</strong><p>오늘·응원은 작은 포인트. 실패·삭제는 아이콘과 명확한 문구를 함께 씁니다.</p></div></div><table><thead><tr><th>화면</th><th>리넨</th><th>파슬리 그린</th><th>토마토 레드</th></tr></thead><tbody>${screens.map(s=>{const c=colorStory(s[0]);return `<tr><td><button data-action="go:${s[0]}">${s[2]} ${icon('chevron')}</button><span class="route-code">${s[3]}</span></td><td>${c.linen}</td><td>${c.green}</td><td>${c.tomato}</td></tr>`;}).join('')}</tbody></table></div>`;}

const sheet=document.querySelector('#sheet');
function openSheet(title,body){sheet.dataset.intent=/삭제|마감|종료|저장하지 못|계정 전환/.test(title)?'caution':'normal';sheet.innerHTML=`<div class="sheet-top"><h2 id="sheet-title">${title}</h2>${ib('x','닫기','close')}</div><div class="sheet-body">${body}</div>`;if(!sheet.open)sheet.showModal();}
function notify(message){const el=document.querySelector('#demo-toast');el.textContent=message;el.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.classList.remove('show'),2600);}
function go(id){sheet.close();state.screen=id;state.mode='detail';history.replaceState(null,'',`#${id}`);render();}
const menu=(items)=>items.map(([i,t,a,danger])=>`<button class="list-row ${danger?'danger':''}" data-action="${a}">${icon(i)}<strong>${t}</strong></button>`).join('');
function statusSheet(){const content={normal:['모두 저장됐어요',`<p>최근 변경이 저장됐어요.</p>${row('folder','기기에 남은 초안','이 계정의 초안 1개','draft')}`],offline:['저장 대기 2개',`<p>오프라인이에요. 입력은 이 기기에 보관되어 있고 연결되면 전송됩니다.</p>${row('edit','오늘의 일기','기기에 보관됨','go:diary')}${row('book','기도 메모','기기에 보관됨','go:noteedit')}${button('연결 확인 후 재시도','retry')}`],conflict:['확인이 필요한 변경 1개',`<p>다른 기기에서 같은 기록을 바꿨어요. 내 입력은 이 기기에 남아 있어요.</p>${row('book','10.28 기도','두 내용을 비교해주세요.','go:conflicts')}`],failed:['기기에 저장하지 못했어요',`<div class="warning-card">입력이 아직 보관되지 않았어요.<br>앱을 닫거나 계정을 바꾸기 전에 확인해주세요.</div><p>저장 공간을 확인한 뒤 다시 시도하세요.</p>${button('다시 저장','retry')}${button('입력 내용 보기','go:noteedit','secondary')}`]}[state.status];openSheet(...content);}
document.addEventListener('change',e=>{if(e.target.id==='status-select'){state.status=e.target.value;render();}if(e.target.matches('.screen-picker'))go(e.target.value);});
document.addEventListener('click',e=>{
 const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;const [key,arg]=action.split(':');const area=el.closest('.phone')||document;
 if(key==='gallery'){state.gallery=arg;render();return;} if(key==='go')return go(arg);if(key==='mode'){state.mode=arg;render();return;}if(key==='close'){sheet.close();return;}
 if(key==='check'){const checked=el.getAttribute('aria-pressed')!=='true';el.setAttribute('aria-pressed',checked);el.closest('.habit-row').classList.toggle('done',checked);return;}
 if(key==='mood'||key==='choice'||key==='day'){el.parentElement.querySelectorAll('button').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false');});el.classList.add('active');el.setAttribute('aria-pressed','true');return;}
 if(key==='toggle'){el.setAttribute('aria-checked',el.getAttribute('aria-checked')==='true'?'false':'true');return;}
 if(key==='filter'){el.parentElement.querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-pressed',b===el?'true':'false');});area.querySelectorAll('[data-category]').forEach(n=>n.hidden=arg!=='전체'&&n.dataset.category!==arg);return;}
 if(key==='stats'){state.stats=arg;render();return;}
 if(key==='remaining'){area.querySelectorAll('.habit-row.done').forEach(n=>n.hidden=!n.hidden);el.classList.toggle('active');return;}
 if(key==='status')return statusSheet();
 if(key==='retry'){state.status='normal';sheet.close();render();notify('시안: 저장 완료 상태로 바뀌었어요.');return;}
 if(key==='save'){if(state.status==='failed')return statusSheet();const title=area.querySelector('.title-field');if(title&&!title.value.trim()){title.focus();notify('이름을 입력해주세요.');return;}notify(state.status==='offline'?'시안: 기기에 보관 · 전송 대기':'시안: 저장했어요. 실제 데이터는 바뀌지 않아요.');return;}
 if(key==='habit-menu')return openSheet('실천 더보기',menu([['timer','타이머 시작','go:timer'],['moon','오늘은 쉬기','rest'],['leaf','작게 실천하기','alternative'],['edit','수정','go:habitform'],['folder','보관','archive-confirm']]));
 if(key==='rest'||key==='alternative'){sheet.close();notify(key==='rest'?'시안: 오늘은 쉬어감으로 기록했어요.':'시안: 대체 실천으로 기록했어요.');return;}
 if(key==='draft')return openSheet('이어 쓰던 내용이 있어요',`<p class="caption muted">10.28 · 이 기기에 보관된 초안</p><div class="card soft"><p>작은 배려를 실천하겠습니다.<br>오늘의 마음을 조금 더 적어두기.</p></div>${button('이어서 쓰기','restore-draft')}${button('현재 내용 유지','close','secondary')}${disclosure('초안 지우기',`<p class="caption">저장된 기록은 유지하고 이 기기의 초안만 지웁니다.</p>${button('초안만 지우기','discard-draft','text-button')}`)}`);
 if(key==='restore-draft'){sheet.close();if(!['diary','noteedit'].includes(state.screen))go('noteedit');const input=document.querySelector('.editor');if(input){input.value='작은 배려를 실천하겠습니다.\n오늘의 마음을 조금 더 적어두기.';input.focus();}notify('시안: 초안을 불러왔어요.');return;}
 if(key==='discard-draft'){sheet.close();notify('시안: 초안만 지웠어요.');return;}
 if(key==='draft-info'){if(state.status==='failed')return statusSheet();return openSheet('기기에 보관 중',`<p>작성 중인 내용은 이 기기의 같은 계정에서 이어 쓸 수 있어요. 다른 기기에서도 보려면 저장을 눌러주세요.</p>${button('확인','close')}`);}
 if(key==='note-menu')return openSheet('기록 관리',menu([['edit','수정','go:noteedit'],['heart','응답 표시','answered'],['trash','기록 삭제','delete-confirm',true]]));
 if(key==='answered'){sheet.close();notify('시안: 응답 상태를 바꿨어요.');return;}
 if(key==='delete-confirm')return openSheet('이 기록을 삭제할까요?',`<p>10월 28일의 선택한 기록만 삭제합니다. 다른 날의 기록은 남아요.</p><p class="caption muted" style="margin-top:12px">서버가 확인할 때까지 목록에 유지돼요.</p>${button('삭제 요청','delete-demo')}${button('취소','close','secondary')}`);
 if(key==='delete-demo'){sheet.close();notify('시안: 삭제 확인 대기 · 실제 기록은 보존됩니다.');return;}
 if(key==='archive-confirm')return openSheet('오늘부터 보관할까요?',`<p>과거 수행 기록은 남아 있어요. 보관한 습관은 보관함에서 다시 시작할 수 있어요.</p>${button('보관','demo-done')}${button('취소','close','secondary')}`);
 if(key==='restore')return openSheet('오늘부터 다시 시작해요',`<p>10월 28일부터 홈에 표시합니다.<br>보관 전 수행 기록은 유지돼요.</p>${button('복원','demo-done')}`);
 if(key==='metric-info')return openSheet('숫자의 기준',`<p><strong>지금까지 기록률</strong><br>오늘까지 예정된 실천 중 기록한 비율.</p><div class="line"></div><p><strong>전체 진척</strong><br>앞으로의 예정일을 포함한 목표 기간 전체의 비율.</p><div class="warning-card">완료·대체·쉼 기록을 포함해요. 일정과 과거 기록은 바뀌지 않습니다.</div>${button('확인','close')}`);
 if(key==='goal-add')return openSheet('어떤 목표를 세울까요?',menu([['calendar','이번 주 목표','go:weeklyform'],['target','이달의 목표','go:goalform']]));
 if(key==='goal-menu')return openSheet('목표 관리',menu([['edit','내용 수정','go:goalform'],['calendar','기간·분류 변경','goal-impact'],['link','실천 연결','go:connect'],['trash','목표 삭제','goal-delete',true]]));
 if(key==='goal-impact')return openSheet('기간을 바꾸면',`<p class="caption muted">10.01–10.31 → 10.01–11.15</p><div class="card soft"><div class="spread"><span>전체 진척</span><b>64% → 43%</b></div></div><p>계산할 기간만 바뀝니다.<br>습관 일정과 과거 기록은 유지돼요.</p>${button('변경 적용','demo-done')}${button('취소','close','secondary')}`);
 if(key==='goal-delete')return openSheet('목표만 삭제할까요?',`<p>연결된 습관 2개와 과거 기록은 남겨두고 오늘부터 목표 연결만 해제합니다.</p>${button('목표만 삭제 요청','delete-demo')}${button('취소','close','secondary')}`);
 if(key==='connection-menu')return openSheet('연결 관리',menu([['link','다른 목표로 이동','move-goal'],['x','목표 연결 해제','unlink-confirm']]));
 if(key==='unlink-confirm')return openSheet('연결을 해제할까요?',`<p>10월 28일부터 이 목표와의 연결만 해제해요. 습관과 이전 수행 기록은 남아요.</p>${button('연결 해제','demo-done')}${button('취소','close','secondary')}`);
 if(key==='move-goal')return openSheet('옮길 목표',`${row('target','꾸준히 몸을 돌보는 사람','11.27까지','move-confirm')}`);
 if(key==='move-confirm')return openSheet('이 목표로 옮길까요?',`<p>10월 28일부터 새 목표에 반영해요.<br>과거 연결과 수행 기록은 남습니다.</p>${button('이동','demo-done')}`);
 if(key==='link-picker'||key==='goal-select')return openSheet(key==='link-picker'?'연결할 습관':'목표 선택',`${row('walk','퇴근 후 산책','개인 · 연결 가능','demo-done')}${row('target','활기찬 아침 만들기','10.31까지','demo-done')}`);
 if(key==='review-next'){state.step=Math.min(4,state.step+1);render();return;}
 if(key==='review-complete')return openSheet('리뷰 저장',`<div class="list-row">${icon('check')} 주간 결산 저장됨</div><div class="list-row">${icon('check')} 실천 조정 저장됨</div><div class="list-row">${icon('alert')} 리뷰 본문 확인 필요</div><p class="caption muted" style="margin-top:12px">저장된 2개는 유지하고 남은 본문만 이어갑니다.</p>${button('남은 1개 저장','review-finish')}`);
 if(key==='review-finish'){state.step=1;go('reviewresult');notify('시안: 남은 항목 저장 완료');return;}
 if(key==='conflict-refresh'){notify('시안: 최신 내용을 다시 확인했어요.');return;}
 if(key==='conflict-confirm'){const value=area.querySelector('input[name="conflict-choice"]:checked').value;return openSheet(value==='mine'?'내 입력을 사용할까요?':'저장된 내용을 사용할까요?',`<p>${value==='mine'?'비교한 내 메모로 저장합니다. 수행 체크와 다른 날짜의 기록은 유지돼요.':'이 기록의 기기 대기 입력을 지우고 저장된 내용을 사용합니다. 다른 기록은 유지돼요.'}</p>${button('이 내용 사용','conflict-finish')}${button('돌아가기','close','secondary')}`);}
 if(key==='conflict-finish'){state.status='normal';go('notes');notify('시안: 선택한 내용으로 정리했어요.');return;}
 if(key==='group-filter'){el.parentElement.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b===el));notify(arg==='mine'?'시안: 참여 중인 모임 2개':'시안: 공개 모집 모임을 둘러봅니다.');return;}
 if(key==='group-tab'){el.parentElement.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b===el));if(arg==='about'){area.querySelector('#group-content').innerHTML=`${section('함께할 일')}<p class="note">점심 뒤 10분씩, 서로의 속도로 걸어요.</p>${section('우리의 약속')}<p class="caption">주 3회 실천 · 서로를 비교하지 않기</p>${option('users','멤버','4/6명','option')}${option('calendar','기간','10.28 – 11.24','period')}${button('참여 상태 확인','membership-status','text-button')}`;}else render();return;}
 if(key==='group-menu')return openSheet('소모임 관리',menu([['lock','초대 관리','invite-manage'],['users','모집 마감','close-recruitment'],['check','모임 종료','end-group'],['shield','신고·차단','safety'],['refresh','요청 상태 확인','membership-status']]));
 if(key==='close-recruitment'||key==='end-group')return openSheet(key==='end-group'?'모임을 종료할까요?':'모집을 마감할까요?',`<p>${key==='end-group'?'기존 모임 기록은 남고 새 활동은 종료됩니다.':'새 멤버 모집만 마감해요. 기존 멤버는 계속 활동합니다.'}</p>${button('상태 변경 요청','membership-status')}${button('취소','close','secondary')}`);
 if(key==='membership-status'||key==='create-group')return openSheet('현재 상태를 확인해주세요',`<p>요청 결과를 확인하지 못했어요. 중복 요청 없이 현재 모임 상태부터 확인합니다.</p>${button('현재 상태 확인','demo-done')}`);
 if(key==='invite-manage')return openSheet('초대 관리',`<p>초대 코드 · 한 명만 사용 · 7일 유효</p>${button('새 초대 만들기','invite-demo')}${button('발급된 초대 보기','invite-demo','secondary')}`);
 if(key==='invite-demo')return openSheet('초대 코드 예시',`<div class="card soft"><strong>ONJU · DEMO · ONLY</strong></div><p class="caption">시안용 코드입니다. 실제 초대는 발급되지 않아요.</p>${button('닫기','close')}`);
 if(key==='invite-preview')return openSheet('초대받은 소모임',`<h3 style="margin-bottom:10px">하루 한 줄 말씀</h3><p class="caption">비공개 · 4/6명 · 11.24까지</p><div class="line"></div><p><strong>우리의 약속</strong><br>하루 한 구절 나누기<br>서로의 기록을 모임 밖에 공유하지 않기</p>${button('약속 확인하고 참여','membership-status')}`);
 if(key==='share-select')return openSheet('공유할 모임',`${row('users','함께 걷는 점심시간','공개 모임 · 멤버 4명','demo-done')}${row('lock','하루 한 줄 말씀','비공개 모임 · 멤버 4명','demo-done')}`);
 if(key==='share-confirm')return openSheet('이 모임에 공유할까요?',`<p><strong>함께 걷는 점심시간</strong><br>선택한 실천 1개와 한마디가 모임 멤버에게 공개됩니다.</p>${button('공유','demo-done')}${button('취소','close','secondary')}`);
 if(key==='permission')return openSheet('알림 권한을 확인해주세요',`<p>휴대폰 설정에서 온주 알림을 허용한 뒤 원하는 알림을 켤 수 있어요.</p><p class="caption muted" style="margin-top:12px">시안에서는 실제 기기 권한을 요청하지 않습니다.</p>${button('확인','close')}`);
 if(key==='account')return openSheet('계정 관리',menu([['user','계정 전환','switch-account'],['lock','로그아웃','switch-account'],['trash','계정 삭제','delete-account',true]]));
 if(key==='switch-account')return openSheet('계정을 전환할까요?',`<p>미전송 입력은 이 계정에 보관됩니다. 다시 로그인하면 이어갈 수 있어요.</p>${button('계정 전환','auth-demo')}${button('취소','close','secondary')}`);
 if(key==='delete-account')return openSheet('계정 삭제 안내',`<p>계정과 서버 기록이 영구 삭제되는 행동입니다. 실제 화면에서는 삭제 범위와 확인 절차를 별도로 표시합니다.</p><p class="caption muted" style="margin-top:12px">이 시안에는 실제 계정 삭제 동작이 없습니다.</p>${button('닫기','close')}`);
 if(key==='life-settings')return openSheet('생활 설정',`${option('calendar','주 시작 요일','월요일','week-start')}${option('clock','전날 체크 마감','오전 6시','day-end')}${disclosure('체크 마감이란?',`<p class="caption">이 시각까지 어제의 실천을 마저 기록할 수 있어요.</p>`)}`);
 if(key==='theme'){area.querySelectorAll('.theme-card').forEach(n=>n.classList.toggle('active',n===el));notify('시안: 선택한 테마');return;}
 if(key==='theme-locked')return openSheet('조금 더 자라면 열려요',`<p>다음 나무 단계에서 이 풍경을 사용할 수 있어요.</p>${button('나의 나무 보기','go:tree')}`);
 if(key==='plus'||key==='minus'){state.count=Math.max(1,Math.min(7,state.count+(key==='plus'?1:-1)));area.querySelector('#target-count').innerHTML=`${state.count}<small> 회</small>`;return;}
 if(key==='timer-play'){const running=el.dataset.running==='true';el.dataset.running=String(!running);el.innerHTML=icon(running?'play':'pause')+(running?'시작':'일시정지');notify('시안: 타이머 조작 상태만 전환해요.');return;}
 if(key==='timer-done')return openSheet('실천을 마쳤나요?',`${button('완료','go:home')}${button('계속하기','close','secondary')}`);
 if(key==='auth-demo'){notify('시안: 실제 인증이나 계정 변경은 하지 않아요.');return;}
 if(key==='demo-done'){sheet.close();notify('시안에서 확인했어요. 실제 기록은 유지됩니다.');return;}
 if(key==='cheer'){el.innerHTML=icon('heart')+' 응원 4';el.setAttribute('aria-pressed','true');return;}
 const info={repeat:['반복',`${['매일','월·수·금','주말'].map(t=>button(t,'demo-done','secondary')).join('')}`],period:['기간',field('시작일','2026-10-28','date')+field('종료일','2026-11-27','date')+button('선택','demo-done')],privacy:['공개 범위',`<p><strong>공개</strong> · 누구나 목록에서 찾을 수 있어요.<br><strong>비공개</strong> · 초대 코드로만 참여해요.</p>${button('비공개로 설정','demo-done')}`],adjust:['실천 조정',`${option('calendar','반복','월·수·금','repeat')}${button('변경 반영','demo-done')}`],alarm:['습관 알림',field('알림 시간','07:00','time')+button('설정','demo-done')],history:['지난 기록',`<p>지난 기간의 기록을 날짜별로 볼 수 있는 상세 화면으로 연결합니다.</p>${button('확인','close')}`],safety:['신고·차단',`<p>신고 사유와 차단 영향을 확인한 뒤 진행합니다. 실제 신고는 전송하지 않습니다.</p>${button('닫기','close')}`]};
 if(info[key])return openSheet(...info[key]);
 openSheet(el.textContent.trim()||el.getAttribute('aria-label')||'설정',`<p>선택 항목을 짧은 설정 시트에서 변경합니다.</p>${button('확인','demo-done')}${button('취소','close','secondary')}`);
});
sheet.addEventListener('click',e=>{if(e.target===sheet){const r=sheet.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)sheet.close();}});
const hash=location.hash.slice(1);if(screens.some(s=>s[0]===hash)){state.screen=hash;state.mode='detail';}
render();
